from azure.identity import DefaultAzureCredential
from azure.storage.blob import BlobServiceClient


def get_object_metadata(object_name, config=None):
    config = config or {}
    with DefaultAzureCredential() as credential:
        with BlobServiceClient(config['account_url'], credential=credential) as client:
            blob = client.get_blob_client(container=config['container'], blob=object_name)
            metadata = blob.get_blob_properties()
    return {'metadata': metadata}

from azure.identity import DefaultAzureCredential
from azure.storage.blob import BlobServiceClient


def list_objects_under_prefix(prefix, config=None):
    config = config or {}
    with DefaultAzureCredential() as credential:
        with BlobServiceClient(config['account_url'], credential=credential) as client:
            blobs = client.get_container_client(config['container']).list_blobs(name_starts_with=prefix)
            object_list = [blob.name for blob in blobs]
    return {'objects': object_list}

from azure.storage.blob import ContentSettings


def normalize_upload_payload(payload):
    normalized_payload = {
        'object_name': payload['object_name'],
        'data': payload['data'],
        'content_type': payload.get('content_type', 'application/octet-stream'),
        'content_settings': ContentSettings(content_type=payload.get('content_type', 'application/octet-stream'))
    }
    return normalized_payload
